using BrudvikWhiteHilt.Helpers;
using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Rowanberries;

/// <summary>
/// Rowanberries, the orange-red berries of a young rowan in the Ashlands. Model: generated by
/// AssetSource/Tools/make_forage_models.py; the berries hide when picked. Voltures sometimes carry them off.
/// </summary>
public class Rowanberries : ForageableBase
{
    /// <summary>
    /// Prefab name of the rowanberries item.
    /// </summary>
    public const string PrefabName = "WhiteHiltRowanberries";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Rowanberries";

    /// <inheritdoc/>
    protected override string Description => "Bitter orange-red berries of the rowan, the tree that saved Thor from the river Vimur. Thunder passes by those who carry it.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Raspberry";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "RaspberryBush";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 5f,
        MinAltitude = 1f,
        MaxTilt = 25f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override string CreatureDropFrom => "Volture";

    /// <inheritdoc/>
    protected override float CreatureDropChance => 0.15f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        // Raspberries turn the orange of rowan berries.
        VisualHelper.RecolorHue(visualRoot, 0.85f, 1f, 0.06f, 1.1f, 1.05f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        ReplaceBushMesh(pickablePrefab, pickable, "rowan", 1.6f);
    }
}
